using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;

var path = "/home/runner/.nuget/packages/xunit.v3.common/1.1.0/lib/netstandard2.0/xunit.v3.common.dll";
using var stream = File.OpenRead(path);
using var peReader = new PEReader(stream);
var metadataReader = peReader.GetMetadataReader();

foreach (var typeDefHandle in metadataReader.TypeDefinitions)
{
    var typeDef = metadataReader.GetTypeDefinition(typeDefHandle);
    var name = metadataReader.GetString(typeDef.Name);
    if (name == "ITestCaseOrderer")
    {
        var ns = metadataReader.GetString(typeDef.Namespace);
        Console.WriteLine($"Found: {ns}.{name}");
        foreach (var methodHandle in typeDef.GetMethods())
        {
            var method = metadataReader.GetMethodDefinition(methodHandle);
            var methodName = metadataReader.GetString(method.Name);
            Console.WriteLine($"  Method: {methodName}");
            foreach (var gpHandle in method.GetGenericParameters())
            {
                var gp = metadataReader.GetGenericParameter(gpHandle);
                var gpName = metadataReader.GetString(gp.Name);
                Console.WriteLine($"    GenParam: {gpName} Attrs: {gp.Attributes}");
                foreach (var constraintHandle in gp.GetConstraints())
                {
                    var constraint = metadataReader.GetGenericParameterConstraint(constraintHandle);
                    // Try to resolve the constraint type
                    if (constraint.Type.Kind == HandleKind.TypeReference)
                    {
                        var typeRef = metadataReader.GetTypeReference((TypeReferenceHandle)constraint.Type);
                        Console.WriteLine($"      Constraint: {metadataReader.GetString(typeRef.Namespace)}.{metadataReader.GetString(typeRef.Name)}");
                    }
                    else if (constraint.Type.Kind == HandleKind.TypeDefinition)
                    {
                        var td = metadataReader.GetTypeDefinition((TypeDefinitionHandle)constraint.Type);
                        Console.WriteLine($"      Constraint: {metadataReader.GetString(td.Namespace)}.{metadataReader.GetString(td.Name)}");
                    }
                }
            }
        }
    }
}
